<?php require_once __DIR__.'/../config/db.php';require_login();$pdo=db();$inventario=$pdo->query('SELECT p.codigo,p.nombre,c.nombre categoria,p.cantidad,p.stock_minimo,p.precio_venta,(p.cantidad*p.precio_venta) valor FROM productos p JOIN categorias c ON c.id_categoria=p.id_categoria ORDER BY p.nombre')->fetchAll();$bajo=array_filter($inventario,fn($r)=>$r['cantidad']<=$r['stock_minimo']);$title='Reportes';require 'header.php';?><div class="d-flex justify-content-between align-items-center mb-3"><h2>Reporte de inventario</h2><button class="btn btn-outline-primary" onclick="window.print()">Imprimir / Guardar PDF</button></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><span>Productos</span><strong><?=count($inventario)?></strong></div></div><div class="col-md-4"><div class="stat-card warning"><span>Bajo stock</span><strong><?=count($bajo)?></strong></div></div><div class="col-md-4"><div class="stat-card"><span>Valor estimado</span><strong>$<?=number_format(array_sum(array_column($inventario,'valor')),0,',','.')?></strong></div></div></div><div class="card"><div class="card-body"><table class="table"><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Stock</th><th>Mínimo</th><th>Precio venta</th><th>Estado</th></tr></thead><tbody><?php foreach($inventario as $r):$b=$r['cantidad']<=$r['stock_minimo'];?><tr><td><?=e($r['codigo'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['categoria'])?></td><td><?=$r['cantidad']?></td><td><?=$r['stock_minimo']?></td><td>$<?=number_format($r['precio_venta'],0,',','.')?></td><td><?=$b?'<span class="badge text-bg-warning">Bajo stock</span>':'<span class="badge text-bg-success">Disponible</span>'?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'footer.php';
